// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

#include "poly1305.h"
#include "global_func_inst.h"

// Replace encrypt vs decrypt specific compute instance with shared one just named poly1305_mac_compute
// Macro includes ID bits to encode is_encrypt
GLOBAL_PIPELINE_INST_W_VALID_ID(poly1305_mac_compute, u320_t, poly1305_mac_loop_body, poly1305_mac_loop_body_in_t)

// Expose global interface that looks like indivdual computes with names including encrypt vs decrypt
stream(poly1305_mac_loop_body_in_t) poly1305_mac_encrypt_compute_in;
uint1_t poly1305_mac_encrypt_compute_in_ready;
stream(poly1305_mac_loop_body_in_t) poly1305_mac_decrypt_compute_in;
uint1_t poly1305_mac_decrypt_compute_in_ready;
stream(u320_t) poly1305_mac_encrypt_compute_out;
uint1_t poly1305_mac_encrypt_compute_out_ready;
stream(u320_t) poly1305_mac_decrypt_compute_out;
uint1_t poly1305_mac_decrypt_compute_out_ready;

// Muxing logic at input and output of compute
#pragma MAIN poly1305_mac_sharing_mux
void poly1305_mac_sharing_mux(){
  // Default no data flowing
  poly1305_mac_compute_in_valid = 0; // into compute
  //poly1305_mac_compute_out_ready = 0; // from compute
  poly1305_mac_encrypt_compute_out.valid = 0; // to encrypt
  poly1305_mac_encrypt_compute_in_ready = 0; // from encrypt
  poly1305_mac_decrypt_compute_out.valid = 0; // to decrypt
  poly1305_mac_decrypt_compute_in_ready = 0; // from decrypt

  // Input side state toggles round robin
  static uint1_t is_encrypt;
  poly1305_mac_compute_in_id = is_encrypt;
  if(is_encrypt){
    poly1305_mac_compute_in = poly1305_mac_encrypt_compute_in.data;
    poly1305_mac_compute_in_valid = poly1305_mac_encrypt_compute_in.valid;
    poly1305_mac_encrypt_compute_in_ready = 1; //poly1305_mac_compute_in_ready;
  }else{
    poly1305_mac_compute_in = poly1305_mac_decrypt_compute_in.data;
    poly1305_mac_compute_in_valid = poly1305_mac_decrypt_compute_in.valid;
    poly1305_mac_decrypt_compute_in_ready = 1; //poly1305_mac_compute_in_ready;
  }
  is_encrypt = ~is_encrypt;

  // Output side muxing based on id flag out of compute
  if(poly1305_mac_compute_out_valid){
    if(poly1305_mac_compute_out_id){ // is_encrypt
      poly1305_mac_encrypt_compute_out.data = poly1305_mac_compute_out;
      poly1305_mac_encrypt_compute_out.valid = poly1305_mac_compute_out_valid;
      //poly1305_mac_compute_out_ready = poly1305_mac_encrypt_compute_out_ready;
    }else{
      poly1305_mac_decrypt_compute_out.data = poly1305_mac_compute_out;
      poly1305_mac_decrypt_compute_out.valid = poly1305_mac_compute_out_valid;
      //poly1305_mac_compute_out_ready = poly1305_mac_decrypt_compute_out_ready;
    }
  }
}

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// Encrypt part of shared design
// intended to look alot like stand alone top level chacha20poly1305_encrypt.c
// without including the shared compute pipelines...
#include "arrays.h"
// Top level IO port config, named like chacha20poly1305_encrypt_*
#include "chacha20poly1305_encrypt.h"
// Instance of chacha20 part of encryption
#define CHACHA_INST chacha20_encrypt
#define CHACHA_EXCLUDES_PIPELINE
#include "../chacha20/chacha20.c"
// Instance of preparing auth data part of encryption
#define PREP_AUTH_DATA_INST prep_auth_data_encrypt
#include "../prep_auth_data/prep_auth_data.c"
// Instance of poly1305 part of encryption using MCP (not shared)
#define POLY_MAC_INST poly1305_mac_encrypt
#include "../poly1305/poly1305_mac.c"
// Instance of the appending auth tag part of encryption
#include "../auth_tag/append_auth_tag.c"
// Instance of encrypt dataflow connecting everything together
#include "encrypt_dataflow.c"

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// Decrypt part of shared design
// intended to look alot like stand alone top level chacha20poly1305_decrypt.c
// without including the shared compute pipelines...
#include "arrays.h"
// Top level IO port config, named like chacha20poly1305_decrypt_*
#include "chacha20poly1305_decrypt.h"
// Instance of chacha20 part of decryption
#define CHACHA_INST chacha20_decrypt
#define CHACHA_EXCLUDES_PIPELINE
#include "../chacha20/chacha20.c"
// Instance of preparing auth data part of decryption
#define PREP_AUTH_DATA_INST prep_auth_data_decrypt
#include "../prep_auth_data/prep_auth_data.c"
// Instance of poly1305 part of decryption using MCP (not shared)
#define POLY_MAC_INST poly1305_mac_decrypt
#include "../poly1305/poly1305_mac.c"
// Instance of the poly1305 verification block
#include "../poly1305/poly1305_verify_decrypt.c"
// Instance of strip auth tag
#include "../auth_tag/strip_auth_tag.c"
// Instance wait to verify block 
#include "../auth_tag/wait_to_verify.c"
// Instance of decrypt dataflow connecting everything together
#include "decrypt_dataflow.c"

// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
// SPDX-FileCopyrightText: 2026 Julian Kammerer
//
// SPDX-License-Identifier: GPL-3.0-or-later

// Instance of chacha20_loop_body
// requires data width converters to-from 512b wide blocks 128b bus
// use axis128/512 stream types
#include "axi/axis.h"
#include "global_func_inst.h"
#include "chacha20.h"
#include "../poly1305/poly1305.h"

#ifndef CHACHA_INST
#define CHACHA_INST chacha20
#endif

// Globally visible ports
// CSR inputs
uint8_t PPCAT(CHACHA_INST,_key)[CHACHA20_KEY_SIZE]; // input
uint8_t PPCAT(CHACHA_INST,_nonce)[CHACHA20_NONCE_SIZE]; // input
// Input plaintext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_in); // input
uint1_t PPCAT(CHACHA_INST,_axis_in_ready); // output
// Output poly1305_key
stream(poly1305_key_uint_t) PPCAT(CHACHA_INST,_poly_key); // output
uint1_t PPCAT(CHACHA_INST,_poly_key_ready); // input
// Output ciphertext
stream(axis128_t) PPCAT(CHACHA_INST,_axis_out); // output
uint1_t PPCAT(CHACHA_INST,_axis_out_ready); // input

#ifndef CHACHA_EXCLUDES_PIPELINE
// Global instance of the chacha20_loop_body pipeline
GLOBAL_VALID_READY_PIPELINE_INST(PPCAT(CHACHA_INST,_pipeline), axis512_t, chacha20_loop_body, chacha20_loop_body_in_t, 64)
#endif

// Instance of FSM to control pipeline
MAIN(CHACHA_INST)
void CHACHA_INST(){
  chacha20_fsm_t fsm_out = chacha20_fsm(
    PPCAT(CHACHA_INST,_key),
    PPCAT(CHACHA_INST,_nonce),
    PPCAT(CHACHA_INST,_axis_in),
    PPCAT(CHACHA_INST,_poly_key_ready),
    PPCAT(CHACHA_INST,_axis_out_ready),
    PPCAT(CHACHA_INST,_pipeline_in_ready),
    PPCAT(CHACHA_INST,_pipeline_out)
  );
  PPCAT(CHACHA_INST,_axis_in_ready) = fsm_out.ready_for_axis_in;
  PPCAT(CHACHA_INST,_poly_key) = fsm_out.poly_key;
  PPCAT(CHACHA_INST,_axis_out) = fsm_out.axis;
  PPCAT(CHACHA_INST,_pipeline_in) = fsm_out.to_pipeline;
  PPCAT(CHACHA_INST,_pipeline_out_ready) = fsm_out.ready_for_from_pipeline;
}

#undef CHACHA_INST

