7	#pragma MAIN_MHZ encrypt_dataflow 80.0
8	void encrypt_dataflow(){
9	    // Connect chacha20poly1305_encrypt_* input stream to chacha20
10	    chacha20_encrypt_axis_in = chacha20poly1305_encrypt_axis_in;
11	    chacha20poly1305_encrypt_axis_in_ready = chacha20_encrypt_axis_in_ready;
12	    chacha20_encrypt_key = chacha20poly1305_encrypt_key;
13	    chacha20_encrypt_nonce = chacha20poly1305_encrypt_nonce;
14	
15	    // Connect chacha20 output poly key into poly1305_mac key input
16	    poly1305_mac_encrypt_key = chacha20_encrypt_poly_key;
17	    chacha20_encrypt_poly_key_ready = poly1305_mac_encrypt_key_ready;
18	
19	    // Connect chacha20 ciphertext output to both
20	    //  prep_auth_data input
21	    //  append auth tag input
22	    // Fork the stream by combining valids and readys
23	    //  default no data passing, invalidate passthrough
24	    prep_auth_data_encrypt_axis_in = chacha20_encrypt_axis_out;
25	    prep_auth_data_encrypt_axis_in.valid = 0;
26	    append_auth_tag_axis_in = chacha20_encrypt_axis_out;
27	    append_auth_tag_axis_in.valid = 0;
28	    //  allow pass through if both sinks are ready
29	    //  or if sink isnt ready (no data passing anyway)
30	    chacha20_encrypt_axis_out_ready = prep_auth_data_encrypt_axis_in_ready & append_auth_tag_axis_in_ready;
31	    if(chacha20_encrypt_axis_out_ready | ~prep_auth_data_encrypt_axis_in_ready){
32	        prep_auth_data_encrypt_axis_in.valid = chacha20_encrypt_axis_out.valid;
33	    }
34	    if(chacha20_encrypt_axis_out_ready | ~append_auth_tag_axis_in_ready){
35	        append_auth_tag_axis_in.valid = chacha20_encrypt_axis_out.valid;
36	    }
37	
38	    // Prep auth data CSR inputs
39	    prep_auth_data_encrypt_aad = chacha20poly1305_encrypt_aad;
40	    prep_auth_data_encrypt_aad_len = chacha20poly1305_encrypt_aad_len;
41	
42	    // Connect prep_auth_data output to poly1305_mac input
43	    poly1305_mac_encrypt_data_in = prep_auth_data_encrypt_axis_out;
44	    prep_auth_data_encrypt_axis_out_ready = poly1305_mac_encrypt_data_in_ready;
45	
46	    // Connect poly1305_mac auth tag output to append auth tag input
47	    append_auth_tag_auth_tag_in = poly1305_mac_encrypt_auth_tag;
48	    poly1305_mac_encrypt_auth_tag_ready = append_auth_tag_auth_tag_in_ready;
49	    
50	    // Connect append auth tag output to chacha20poly1305_encrypt_* output
51	    chacha20poly1305_encrypt_axis_out = append_auth_tag_axis_out;
52	    append_auth_tag_axis_out_ready = chacha20poly1305_encrypt_axis_out_ready;
53	}
