242	// Is actually two independent FSMs
243	// one handling inputs to the pipeline
244	// and another handling output from the pipeline
245	
246	// Two uses of the chacha20_pipeline
247	typedef enum chacha20_state_t{
248	  POLY_KEY,
249	  PLAINTEXT
250	} chacha20_state_t;
251	
252	typedef struct chacha20_fsm_t{
253	  // Outputs
254	  uint1_t ready_for_axis_in;
255	  stream(poly1305_key_uint_t) poly_key;
256	  stream(axis128_t) axis;
257	  stream(chacha20_loop_body_in_t) to_pipeline;
258	  uint1_t ready_for_from_pipeline;
259	}chacha20_fsm_t;
260	chacha20_fsm_t chacha20_fsm(
261	  // Inputs
262	  uint8_t key[CHACHA20_KEY_SIZE],
263	  uint8_t nonce[CHACHA20_NONCE_SIZE],
264	  stream(axis128_t) axis_in,
265	  uint1_t ready_for_poly_key_out,
266	  uint1_t ready_for_axis_out,
267	  uint1_t to_pipeline_ready,
268	  stream(axis512_t) from_pipeline
269	){
270	  chacha20_fsm_t o;
271	
272	  // INPUT SIDE FSM
273	  // Puts poly1305_key_gen blocks=0,count=0 followed by plaintext into pipeline 
274	  
275	  // Pipeline input muxing FSM
276	  static chacha20_state_t input_side_state;
277	  static uint32_t block_count = 0;
278	  // Default no input into width conversion
279	  stream(axis128_t) dwidth_conv_data_in = {0};
280	  o.ready_for_axis_in = 0;
281	  // Default no input into pipeline
282	  stream(chacha20_loop_body_in_t) NULL_PIPELINE_IN = {0};
283	  o.to_pipeline = NULL_PIPELINE_IN;
284	  //  other than CSR inputs and such
285	  o.to_pipeline.data.key = key;
286	  o.to_pipeline.data.nonce = nonce;
287	  o.to_pipeline.data.counter = block_count;
288	  
289	  // Convert input axis to 512b
290	  // Input axis into dwidth conv default gated until in plaintext state
291	  if(input_side_state == PLAINTEXT){
292	    dwidth_conv_data_in = axis_in;
293	  }
294	  uint1_t block_in_ready;
295	  #pragma FEEDBACK block_in_ready
296	  axis128_to_axis512_t in_to_block = axis128_to_axis512(dwidth_conv_data_in, block_in_ready);
297	  stream(axis512_t) block_in_stream = in_to_block.axis_out;
298	  // Default not ready for incoming blocks
299	  block_in_ready = 0;
300	  // Input axis into dwidth conv default gated until in plaintext state
301	  if(input_side_state == PLAINTEXT){
302	    o.ready_for_axis_in = in_to_block.axis_in_ready;
303	  }
304	  
305	  if(input_side_state == POLY_KEY){
306	    // Wait for incoming plaintext
307	    if(axis_in.valid | block_in_stream.valid){
308	      // Do poly1305_key_gen, use counter 0 and generate a block
309	      // Start by putting zero data and block_count=0 into chacha pipeline
310	      ARRAY_SET(o.to_pipeline.data.axis_in.tdata, 0, CHACHA20_BLOCK_SIZE)
311	      ARRAY_SET(o.to_pipeline.data.axis_in.tkeep, 1, CHACHA20_BLOCK_SIZE)
312	      o.to_pipeline.valid = 1;
313	      // Wait until data accepted into pipeline
314	      if(to_pipeline_ready){
315	        block_count += 1;
316	        // then allow a packet of plaintext to flow into the pipeline
317	        input_side_state = PLAINTEXT;
318	      }
319	    }
320	  }else{ //if(input_side_state == PLAINTEXT){
321	    o.to_pipeline.data.axis_in = block_in_stream.data;
322	    o.to_pipeline.valid = block_in_stream.valid;
323	    block_in_ready = to_pipeline_ready; // FEEDBACK
324	    if(o.to_pipeline.valid & to_pipeline_ready){
325	      block_count += 1;
326	      // if this was last block into pipeline then reset counter and poly key next
327	      if(o.to_pipeline.data.axis_in.tlast){
328	        block_count = 0;
329	        input_side_state = POLY_KEY;
330	      }
331	    }
332	  }
333	
334	  // Output side FSM
335	  // Get poly1305_key_gen data or ciphertext out of pipeline
336	
337	  // Pipeline output demuxing FSM
338	  static chacha20_state_t output_side_state;
339	  // Default not ready for pipeline output
340	  o.ready_for_from_pipeline = 0;
341	  // Default no block going out
342	  stream(axis512_t) block_to_out_axis_in = {0};
343	  uint1_t block_to_out_axis_in_ready;
344	  #pragma FEEDBACK block_to_out_axis_in_ready
345	  if(output_side_state == POLY_KEY){
346	    // Wait for the poly key cycle of data to come out of the pipeline
347	    // it goes out the poly1305_key output stream
348	    // First 32 bytes of the block become the Poly1305 key
349	    uint8_t poly_key[POLY1305_KEY_SIZE];
350	    ARRAY_COPY(poly_key, from_pipeline.data.tdata, POLY1305_KEY_SIZE)
351	    o.poly_key.data = poly1305_key_uint_from_bytes(poly_key);
352	    o.poly_key.valid = from_pipeline.valid;
353	    o.ready_for_from_pipeline = ready_for_poly_key_out;
354	    // When output of key happens move on to plaintext
355	    if(o.poly_key.valid & ready_for_poly_key_out){
356	      output_side_state = PLAINTEXT;
357	    }
358	  }else{ //if(output_side_state == PLAINTEXT)
359	    // Wait for the last cycle of ciphertext data to come out of the pipeline
360	    block_to_out_axis_in = from_pipeline;
361	    o.ready_for_from_pipeline = block_to_out_axis_in_ready;
362	    if(from_pipeline.valid & o.ready_for_from_pipeline){
363	      // If this was last block then reset state
364	      if(from_pipeline.data.tlast){
365	        output_side_state = POLY_KEY;
366	      }
367	    }
368	  }
369	
370	  // Convert pipeline output 512b block stream to 128b
371	  axis512_to_axis128_t block_to_out = axis512_to_axis128(block_to_out_axis_in, ready_for_axis_out);
372	  o.axis = block_to_out.axis_out;
373	  block_to_out_axis_in_ready = block_to_out.axis_in_ready; // FEEDBACK
374	
375	  return o;
376	}
