434	  }else if(state == A_PLUS_S){
435	    // a += s
436	    a = uint320_add(a, s);
437	    // Output a next
438	    state = OUTPUT_AUTH_TAG;
439	  }else if(state == OUTPUT_AUTH_TAG){
440	    // First 16 bytes of 'a' are the output  
441	    u320_t_bytes_t a_bytes = u320_t_to_bytes(a);
442	    uint8_t auth_tag[POLY1305_AUTH_TAG_SIZE];
