451	  // latency reduction = throughput increase in this case...
452	  if(state == START_ITER){
453	    // Ready to take an input data block
454	    o.ready_for_data_in = ready_for_to_compute;
455	    // Put 'a' and data block into compute
456	    o.to_compute.block_bytes = data_in.data.tdata;
